        aragonite: {
            DisplayName: "Aragonite",
            Category: "Crystal",

            Element: "Earth",

            Planet: "Saturn",

            Chakra: "Root",

            Uses: "Grounding, patience, stability, steadiness under stress",

            PairsWith: "Smoky quartz, brown candle, oak, red jasper",

            Cleansing: "Smoke, sound, earth",

            TraditionalWarnings: "Aragonite is soft and dissolves in acids, even vinegar or lemon juice. Keep it out of water soaks and salt.",

            Overview: "Aragonite is calcium carbonate, the same chemistry as calcite but a different crystal structure, and only Mohs 3.5–4. It comes in brown, orange, white and pale blue, and the best-known pieces are the spiky orange-brown ‘star clusters’ from Morocco; it was named after Aragon in Spain. It is sold as star clusters, tumbled stones, carvings and chips.",

            TraditionalMeaning: "Patience and steady footing; a modern earthy stone of grounding, calm under pressure and staying the course.",

            HowToUse: "Start here: set an aragonite star cluster on your desk or altar and rest your hand beside it for a few slow breaths when a day feels scattered. Tumbled pieces can be carried, and chips can go into dry jars for grounding. Handle star clusters by the base, as the points snap easily.",

            PairingNotes: "Aragonite pairs well with smoky quartz for grounding, brown candles for stability and the home, oak for endurance, and red jasper for steady strength. Black tourmaline can add protection to its calm.",

            CleansingNotes: "Cleanse aragonite with smoke, sound, earth, or visualization. A quick wipe with a barely damp cloth is the most water it needs; never soak it or rest it in salt, and keep it away from vinegar and citrus.",

            SafetyAndRespect: "Aragonite is safe to handle but soft and brittle; star clusters break easily and shed small spikes, so keep them from small children and pets. Its grounding meanings are modern crystal lore rather than older tradition, and it is no substitute for care when stress becomes too much.",

            Traditions: "Wheel of the Year",

            TraditionNotes: "Wheel of the Year: Kept on the altar or in the home as a grounding stone, set at the base of grids for stability, and held after ritual to come back into the body; often used in earth-centred work and at the waning moon.\n\nFolk & wider practice: Aragonite has no long magical history of its own; its meanings come from late 20th-century crystal-healing books. The same mineral builds seashells and the nacre of pearls, which is why some practitioners link it to the sea and to slow, patient growth.",

            tags: ["grounding", "patience", "stability", "calm", "root", "saturn"]
        },

        azurite: {
            DisplayName: "Azurite",
            Category: "Crystal",

            Element: "Water",

            Planet: "Venus",

            Chakra: "Third Eye",

            Uses: "Insight, study, intuition, clear thinking, inner vision",

            PairsWith: "Malachite, indigo candle, mugwort, lapis lazuli",

            Cleansing: "Smoke, sound",

            TraditionalWarnings: "Azurite contains copper. Do not make elixirs or gem water with it, never cut, sand or polish it yourself, and keep it out of water, salt and strong light.",

            Overview: "Azurite is a deep, inky blue copper carbonate, only Mohs 3.5–4, that forms as small crystals, crusts and round nodules, often grown together with green malachite as ‘azurmalachite’. Fine pieces come from Arizona, Namibia, Morocco, France and China. It is sold as raw specimens, nodules (‘blueberries’), polished pieces and cabochons.",

            TraditionalMeaning: "Insight and inner sight; a deep blue modern stone of study, intuition and seeing a problem clearly.",

            HowToUse: "Start here: set a polished azurite or a sealed specimen beside your books or journal while you study or reflect, and look at it before you begin. Keep raw pieces in a box or display case rather than handling them, and choose polished or stabilised pieces if you want to hold one. Store it out of bright light.",

            PairingNotes: "Azurite pairs naturally with malachite, which it often grows beside, for insight that leads to change. Indigo candles suit inner sight, mugwort supports dreams and divination, and lapis lazuli adds wisdom and truth.",

            CleansingNotes: "Cleanse azurite with smoke, sound, or visualization only. Water, salt, heat and long light can dull or damage it, and raw azurite should not be buried in garden soil.",

            SafetyAndRespect: "Azurite contains copper and its dust is toxic. Polished pieces are fine to hold briefly, but wash your hands after handling raw specimens, never put it in drinking water or elixirs, and keep it away from children and pets. Over time azurite slowly weathers to malachite, which is why some old blue paint has turned green.",

            Traditions: "Wheel of the Year",

            TraditionNotes: "Wheel of the Year: Held or placed on the altar for divination, dreamwork and study, set beside indigo or blue candles in spells for insight and clear sight, and used in meditation; favoured at the full moon.\n\nFolk & wider practice: Ground azurite was one of the main blue pigments of medieval and Renaissance European painting, and was used in Chinese painting too. Its link to Venus comes from its copper, Venus’s metal in alchemy, and its ‘psychic’ meanings are modern crystal-healing lore rather than older tradition.",

            tags: ["insight", "intuition", "study", "clarity", "third eye", "venus"]
        },

