            TraditionNotes: "Wheel of the Year: Carried or placed on the altar during times of change, used in spells for courage and releasing fear, and held in meditation for spiritual growth; often worked at the waning moon and at Samhain.\n\nFolk & wider practice: Charoite was only described in 1978 and named after the Chara River; a popular story links the name to the Russian word for magic or charms, but the river is the real source. All its magical meanings are modern.",

